package net.civeira.phylax.feature.observe.observedissuealias.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissuealias.domain.ObservedIssueAlias;
import net.civeira.phylax.feature.observe.observedissuealias.domain.valueobject.FingerprintVO;

@RequiredArgsConstructor
public class FingerprintValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<FingerprintVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param fingerprint
   * @return
   */
  public T fingerprint(FingerprintVO fingerprint) {
    this.value = Optional.of(fingerprint);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param fingerprint
   * @return
   */
  public T fingerprint(Optional<FingerprintVO> fingerprint) {
    this.value = fingerprint;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param fingerprint
   * @return
   */
  public T fingerprint(String fingerprint) {
    this.value = Optional.of(FingerprintVO.from(fingerprint));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getFingerprint() {
    return value.map(FingerprintVO::getFingerprint);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<FingerprintVO> getFingerprintValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public FingerprintVO readFingerprint(final Optional<ObservedIssueAlias> original,
      final ConstraintFailList fails) {
    FingerprintVO result =
        value.orElse(original.map(ObservedIssueAlias::getFingerprintValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "fingerprint", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetFingerprint() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetFingerprintIfMatches(final String field) {
    if ("fingerprint".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
